draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // character 1
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2 - 50, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 + 20);
  ctx.lineTo(W/2 - 50, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 + 25);
  ctx.lineTo(W/2 - 70, H/2 + 40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 + 25);
  ctx.lineTo(W/2 - 30, H/2 + 40);
  ctx.stroke();

  // character 2
  ctx.beginPath();
  ctx.arc(W/2 + 50, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50, H/2 + 20);
  ctx.lineTo(W/2 + 50, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50, H/2 + 25);
  ctx.lineTo(W/2 + 70, H/2 + 40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50, H/2 + 25);
  ctx.lineTo(W/2 + 30, H/2 + 40);
  ctx.stroke();

  // helping action
  ctx.beginPath();
  ctx.moveTo(W/2 - 30, H/2 + 60 + 20 * Math.sin(t));
  ctx.lineTo(W/2 + 30, H/2 + 60 + 20 * Math.sin(t));
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2, H/2 + 60 + 20 * Math.sin(t), 10, 0, 2 * Math.PI);
  ctx.stroke();

  ctx.restore();
}
